function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 9);
  const top = size === 'large' ? 100000 : 20;
  const seen = new Set();
  const nums = [];
  while (nums.length < n) {
    const value = 1 + Math.floor(rand() * top);
    if (!seen.has(value)) {
      seen.add(value);
      nums.push(value);
    }
  }
  const shape = Math.floor(rand() * 5);
  if (shape === 0) nums.sort((a, b) => a - b);
  if (shape === 1) nums.sort((a, b) => b - a);
  if (shape === 2) {
    // A "mountain": rising then falling, so ranges grow toward the peak.
    nums.sort((a, b) => a - b);
    const rising = nums.filter((_, k) => k % 2 === 0);
    const falling = nums.filter((_, k) => k % 2 === 1).reverse();
    return [rising.concat(falling)];
  }
  return [nums];
}
